package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextUniversalFamilyInspection.*;
import org.kanger.ContextUniversalUnitProof.Proof;
import org.kanger.enums.StorageLifecycleErrorCode;
import org.kanger.exception.ContextProductionCommitException;

/** Independent input variables and repeated output coordinates retain their bindings. */
final class ContextAuthorityVariables {
    static int checks;static final int WORK=64000000;
    static void require(boolean yes,String why){++checks;if(!yes)throw new AssertionError(why);}
    static ContextUniversalCandidate.Evaluation inspect(ContextSevenPremiseNativeWriteRunner.Fixture f,String text,int rounds)throws Exception{return f.db.qualifyUniversalProductionCandidate(f.root,text,1000,rounds,16,16,20000,1000000,WORK,500000,WORK);}
    static void units(ContextUniversalUnitRounds.Frontier f,String predicate,int depth,List<Set<Source>> expected,List<SemanticTermSnapshot> coordinates,boolean negative){Set<Set<Source>> actual=new HashSet<>();int count=0;for(ContextUniversalUnitLedger.Row row:f.products)if(row.clause.literals.size()==1){Atom atom=row.clause.literals.get(0);if(!atom.predicate.equals(predicate))continue;++count;require(atom.positive!=negative&&row.clause.variables.isEmpty()&&ground(atom,coordinates)&&row.support.depth==depth&&actual.add(row.support.sources),"exact signed ordered unit, whole support and cumulative depth");}require(count==expected.size()&&actual.equals(new HashSet<>(expected)),"all exact ordered alternatives for "+predicate);}
    static void consistent(Result r,ContextAuthorityChain.Expected e,List<SemanticTermSnapshot> target){consistent(r,e,target,false);}
    static void consistent(Result r,ContextAuthorityChain.Expected e,List<SemanticTermSnapshot> target,boolean permuted){
        require(r.status==Status.CONSISTENT&&r.collision==null&&r.certificate!=null&&r.completedBarriers>=2,"compatible coordinate theory has complete stable-family consistency");ContextUniversalFamilyModel.Certificate c=r.certificate;require(c.cuts.size()==7&&c.input.cuts.size()==7,"all seven exact cuts have models");List<ContextUniversalUnitRounds.Receipt> receipts=new ArrayList<>();List<ContextUniversalQuotientModel.Model> models=new ArrayList<>();for(ContextUniversalFamilyModel.Cut cut:c.cuts){receipts.add(cut.receipt);models.add(cut.model);require(cut.receipt.verified&&cut.receipt.input==c.input&&cut.model.ledger==cut.receipt.closureStep.input,"model bound to exact private closure");}require(ContextUniversalFamilyModel.certify(c.input,receipts,models,16,20000,WORK).certified,"independently recheck all-value stable-family certificate");
        List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}List<SemanticTermSnapshot> coordinates=permuted?Arrays.asList(target.get(1),target.get(0)):Arrays.asList(target.get(0),target.get(0));units(c.input,"out",3,out,coordinates,e.negativeOut);units(c.input,"mid",4,mid,coordinates,e.negative);require(c.input.products.stream().filter(row->row.clause.literals.size()==1).count()==9,"only three out and six mid units, no private donor import or wrong-coordinate counterproduction");
    }
    static List<SemanticTermSnapshot> deny(ContextProductionCandidate.Staged a,ContextAuthorityChain.Expected e){List<SemanticTermSnapshot> result=new ArrayList<>();for(Slot slot:a.foreign.stream().flatMap(c->c.primary.stream()).filter(row->row.source.equals(e.deny)).findFirst().get().clauses.get(0).literals.get(0).arguments)result.add(slot.value);require(result.size()==2&&result.stream().allMatch(Objects::nonNull)&&!result.get(0).semanticallyEquals(result.get(1)),"actual deny is an off-diagonal ground pair");return result;}
    static boolean ground(Atom atom,List<SemanticTermSnapshot> target){if(atom.arguments.size()!=2)return false;for(int i=0;i<2;i++)if(atom.arguments.get(i).variable>=0||!atom.arguments.get(i).value.semanticallyEquals(target.get(i)))return false;return true;}
    static void collision(Result r,ContextAuthorityChain.Expected e,List<SemanticTermSnapshot> target,boolean exactLocal){
        require(r.status==Status.COLLISION&&r.certificate==null&&r.completedBarriers==3&&r.collision.oppositions.size()==12,"conflict variables prove complete third-barrier conflict");Map<Set<Source>,Set<String>> actual=new HashMap<>();Set<Set<Source>> expected=e.pairs();
        for(Proof p:r.collision.oppositions){require(p.contradiction&&p.dependsOnX&&p.conclusion==null&&p.support.depth==5&&p.left.literals.size()==1&&p.right.literals.size()==1,"whole binary unit opposition and depth5");Atom l=p.left.literals.get(0),rr=p.right.literals.get(0);require(l.predicate.equals(rr.predicate)&&l.positive!=rr.positive&&ground(rr,target),"derived opposition retains exact ordered off-diagonal coordinates");require((l.predicate.equals("q")&&l.arguments.size()==2&&l.arguments.get(0).variable>=0&&l.arguments.get(1).variable>=0&&l.arguments.get(0).variable!=l.arguments.get(1).variable&&l.positive!=e.negativeQ&&p.leftSupport.sources.stream().anyMatch(e.authorities::contains))||(l.predicate.equals("mid")&&ground(l,target)&&l.positive==e.negative&&p.leftSupport.sources.contains(e.deny)),"two conflict donor variables or exact ground deny endpoint");require(p.leftSupport.depth==0&&p.leftSupport.sources.size()==1&&p.rightSupport.depth==4&&p.rightSupport.sources.size()==5,"original private source versus transported whole five-source proof");Set<Source> local=new HashSet<>(),foreign=new HashSet<>();for(Source source:p.support.sources)(source.localX?local:foreign).add(source);Set<Source> pair=new HashSet<>(foreign);pair.remove(e.deny);require(p.support.sources.size()==6&&local.size()==3&&foreign.size()==3&&foreign.contains(e.deny)&&expected.contains(pair),"whole X plus one exact donor/Bridge pair and deny");if(exactLocal)require(local.equals(e.locals),"exact fresh staged local Sources");require(actual.computeIfAbsent(pair,k->new HashSet<>()).add(l.predicate),"unique endpoint per conflict pair");}
        require(actual.keySet().equals(expected)&&actual.values().stream().allMatch(v->v.equals(new HashSet<>(Arrays.asList("q","mid")))),"all six exact independently enumerated pairs at both endpoints");
    }
    static void permutationBarriers(ContextProductionCandidate.Staged a,ContextAuthorityChain.Expected e,List<SemanticTermSnapshot> target,boolean swappedBridge){
        ContextUniversalUnitRounds.Frontier initial=ContextUniversalUnitRounds.start(a.staged,a.foreign,WORK);ContextUniversalUnitRounds.Barrier first=ContextUniversalUnitRounds.merge(initial,ContextUniversalAuthorityChain.pass(initial,16),16,WORK);require(first.status==ContextUniversalUnitRounds.Status.MERGED&&first.changed&&initial.products.isEmpty(),"first immutable permutation barrier");List<Set<Source>> out=new ArrayList<>(),mid=new ArrayList<>(),counter=new ArrayList<>();for(Source donor:e.authorities){out.add(e.set(donor));for(Source bridge:e.bridges)mid.add(e.set(donor,bridge));}for(Source bridge:e.bridges)counter.add(e.set(bridge,e.deny));List<SemanticTermSnapshot> reversed=Arrays.asList(target.get(1),target.get(0));units(first.frontier,"out",3,out,reversed,e.negativeOut);int saved=first.frontier.products.size();require(first.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==3,"first barrier exports exactly three swapped out units");ContextUniversalUnitRounds.Barrier second=ContextUniversalUnitRounds.merge(first.frontier,ContextUniversalAuthorityChain.pass(first.frontier,16),16,WORK);require(second.status==ContextUniversalUnitRounds.Status.MERGED&&second.changed&&first.frontier.products.size()==saved,"second immutable permutation barrier preserves earlier frontier");units(second.frontier,"out",3,out,reversed,e.negativeOut);units(second.frontier,"mid",4,mid,swappedBridge?target:reversed,e.negative);if(swappedBridge)units(second.frontier,"q",4,counter,target,!e.negativeQ);require(second.frontier.products.stream().filter(row->row.clause.literals.size()==1).count()==(swappedBridge?11:9),"exact common units after one or two permutations");
    }
    static void caseOf(Path dir,String name,boolean reverse,boolean negative,boolean conflict,boolean nativePath,String text,boolean permuted)throws Exception{
        Set<String> persisted;List<RevisionRef> pins;long settled;
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){
            require(f.root.compile("!~p1(1); !~p2(2);",null,false),"two exact local premise assertions");List<String> names=new ArrayList<>(Arrays.asList("A1","A2","A3","Bridge1","Bridge2","Deny"));if(reverse)Collections.reverse(names);for(String target:names)f.db.connectContext(target);f.db.saveConnections(f.root);
            ContextProductionInventory baseline=ContextSevenPremiseNativeWriteRunner.inventory(f);Set<String> initial=ContextSevenPremiseNativeWriteRunner.origins(baseline);pins=ContextSevenPremiseNativeWriteRunner.pins(f);long revision=f.db.getRevision();int rows=f.root.getRules().size();require(initial.size()==2&&pins.size()==6,"only two local primary facts and six saved pins");
            ContextUniversalCandidate.Evaluation diagnostic=inspect(f,text,16);require(diagnostic.status==(conflict?Status.COLLISION:Status.CONSISTENT),"exact variable/permutation verdict: "+diagnostic.reason);
            ContextAuthorityChain.Expected expected=new ContextAuthorityChain.Expected(diagnostic.artifact,2,negative,negative,negative,false);List<SemanticTermSnapshot> value=deny(diagnostic.artifact,expected);Map<String,SemanticTermSnapshot> values=new HashMap<>();
            int donors=0,bridges=0;Clause donorShape=null,bridgeShape=null;for(org.kanger.ContextProductionNativeBinding.Snapshot cut:diagnostic.artifact.foreign)for(Entry entry:cut.primary){Clause c=entry.clauses.get(0);if(expected.authorities.contains(entry.source)){++donors;if(permuted){if(donorShape==null)donorShape=c;else require(c.equivalent(donorShape),"renamed donor declarations are alpha-equivalent but retain distinct Sources");}Atom atom=c.literals.get(0);require(c.variables.size()==2&&c.literals.size()==1&&atom.arguments.size()==2&&atom.arguments.get(0).variable>=0&&atom.arguments.get(1).variable>=0&&atom.arguments.get(0).variable!=atom.arguments.get(1).variable,"whole private donor has two independently bound coordinates");}if(expected.bridges.contains(entry.source)){++bridges;if(permuted){if(bridgeShape==null)bridgeShape=c;else require(c.equivalent(bridgeShape),"renamed Bridge declarations are alpha-equivalent but retain distinct Sources");}Atom o=c.literals.stream().filter(atom->atom.predicate.equals("out")).findFirst().get(),m=c.literals.stream().filter(atom->atom.predicate.equals("mid")).findFirst().get();require(c.variables.size()==2&&c.literals.size()==2&&o.arguments.size()==2&&m.arguments.size()==2&&o.arguments.get(0).variable>=0&&o.arguments.get(1).variable>=0&&o.arguments.get(0).variable!=o.arguments.get(1).variable&&m.arguments.get(0).variable==o.arguments.get(permuted&&conflict?1:0).variable&&m.arguments.get(1).variable==o.arguments.get(permuted&&conflict?0:1).variable,"whole private Bridge has the requested ordered coordinate mapping");}}require(donors==3&&bridges==2,"all five quantified private declarations checked");
            for(Entry entry:diagnostic.artifact.base.primary){Clause c=entry.clauses.get(0);require(c.variables.isEmpty()&&c.literals.size()==1&&!c.literals.get(0).positive&&c.literals.get(0).arguments.size()==1,"original ground negative local premise");Atom atom=c.literals.get(0);values.put(atom.predicate,atom.arguments.get(0).value);}
            require(values.size()==2&&values.containsKey("p1")&&values.containsKey("p2"),"two distinct premise predicates retained");require(!values.get("p1").semanticallyEquals(values.get("p2"))&&values.get("p1").semanticallyEquals(value.get(0))&&values.get("p2").semanticallyEquals(value.get(1)),"distinct premise values match exact ordered deny coordinates");
            Clause candidate=diagnostic.artifact.staged.primary.stream().filter(e->e.source.equals(diagnostic.artifact.candidate)).findFirst().get().clauses.get(0);Map<String,Atom> atoms=new HashMap<>();for(Atom atom:candidate.literals)atoms.put(atom.predicate,atom);Atom q=atoms.get("q"),out=atoms.get("out");require(candidate.variables.size()==2&&candidate.literals.size()==4&&q.arguments.size()==2&&out.arguments.size()==2,"actual candidate has two quantified variables and binary endpoints");int x=q.arguments.get(0).variable,y=q.arguments.get(1).variable;require(x>=0&&y>=0&&x!=y&&atoms.get("p1").arguments.size()==1&&atoms.get("p1").arguments.get(0).variable==x&&atoms.get("p2").arguments.size()==1&&atoms.get("p2").arguments.get(0).variable==y&&out.arguments.get(0).variable==(permuted?y:x)&&out.arguments.get(1).variable==(permuted?x:(conflict?y:x)),"independent input bindings and exact requested output coordinate pattern");
            if(conflict)collision(diagnostic.qualification,expected,value,true);else consistent(diagnostic.qualification,expected,value,permuted);
            if(permuted){String sign=negative?"~":"";String canonical="!@x @y "+sign+"q(x,y)&&~p1(x)&&~p2(y)->"+sign+"out(y,x);";ContextUniversalCandidate.Evaluation alpha=inspect(f,canonical,16);require(alpha!=diagnostic&&alpha.status==diagnostic.status,"alpha-renamed candidate has the same fresh verdict");Clause shape=alpha.artifact.staged.primary.stream().filter(e->e.source.equals(alpha.artifact.candidate)).findFirst().get().clauses.get(0);require(shape.equivalent(candidate),"canonical and renamed candidate clauses are alpha-equivalent");ContextAuthorityChain.Expected alphaExpected=new ContextAuthorityChain.Expected(alpha.artifact,2,negative,negative,negative,false);if(conflict)collision(alpha.qualification,alphaExpected,deny(alpha.artifact,alphaExpected),true);else consistent(alpha.qualification,alphaExpected,deny(alpha.artifact,alphaExpected),true);permutationBarriers(diagnostic.artifact,expected,value,conflict);}
            ContextUniversalCandidate.Evaluation stopped=inspect(f,text,1);require(stopped.status==Status.INCOMPLETE&&stopped.qualification.certificate==null&&stopped.qualification.collision==null&&stopped.reason.contains("common round limit"),"one common round cannot certify or expose opposition prefix");
            require(f.db.getRevision()==revision&&f.root.getRules().size()==rows&&ContextSevenPremiseNativeWriteRunner.inventory(f).fingerprint.equals(baseline.fingerprint)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"diagnostics preserve exact physical parent and topology");
            if(nativePath){ContextPendingNativeWrite attempt=f.db.beginUniversalWrite(f.root,1000,16,16,16,20000,1000000,WORK,500000,WORK,WORK);try{ContextProductionCommitException failure=null;try{f.root.query(text,null,false);}catch(ContextProductionCommitException caught){failure=caught;}if(conflict){require(failure!=null&&failure.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&failure.getFamilyAudit()!=null&&failure.getFamilyAudit().verified,"actual native conflict independently audited");require(failure.getFamilyAudit().verdict!=diagnostic.qualification,"native guard uses a fresh actual-child verdict");collision(failure.getFamilyAudit().verdict,expected,value,false);}else require(failure==null,"actual native consistent candidate accepted");}finally{f.db.endNativeWrite(attempt);}}
            else{DB.UniversalProductionWriteResult result=f.db.writeUniversalProductionCandidate(f.root,text,1000,16,16,16,20000,1000000,WORK,500000,WORK,WORK,false);require(result.status==(conflict?DB.ProductionWriteStatus.COLLISION:DB.ProductionWriteStatus.PUBLISHED),"fresh public writer reaches expected settlement: "+result.status+" / "+result.trial.reason);require(result.trial!=diagnostic&&result.audit!=null&&result.audit.verified&&result.audit.evaluation==result.trial,"historical diagnostic is not publication authority");require(result.before.getRevision()==revision&&result.after.getRevision()==f.db.getRevision(),"exact pretrial and physical settlement references");if(conflict){ContextAuthorityChain.Expected fresh=new ContextAuthorityChain.Expected(result.trial.artifact,2,negative,negative,negative,false);collision(result.trial.qualification,fresh,deny(result.trial.artifact,fresh),true);}else{require(result.audit.oppositions.isEmpty(),"consistent publication has no collision attribution");ContextAuthorityChain.Expected fresh=new ContextAuthorityChain.Expected(result.trial.artifact,2,negative,negative,negative,false);consistent(result.trial.qualification,fresh,deny(result.trial.artifact,fresh),permuted);}}
            ContextProductionInventory current=ContextSevenPremiseNativeWriteRunner.inventory(f);persisted=ContextSevenPremiseNativeWriteRunner.origins(current);settled=f.db.getRevision();require(ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"publication/refusal retains exact pinned order");
            if(conflict)require(settled==revision&&f.root.getRules().size()==rows&&current.fingerprint.equals(baseline.fingerprint)&&persisted.equals(initial),"conflict refusal retains exact original physical theory");
            else{require(settled>revision&&current.primary.size()==3&&persisted.size()==3&&persisted.containsAll(initial),"only one new whole rule is durably published");ContextProductionNativeBinding.Result bound=ContextProductionNativeBinding.bind(f.root,current,WORK,500000);require(bound.bound&&bound.snapshot.primary.size()==3&&bound.snapshot.primary.stream().anyMatch(e->e.clauses.size()==1&&e.clauses.get(0).equivalent(candidate)),"actual published primary equals the requested universal candidate");require(bound.snapshot.primary.stream().allMatch(e->e.clauses.size()==1&&(e.clauses.get(0).equivalent(candidate)||(e.clauses.get(0).literals.size()==1&&!e.clauses.get(0).literals.get(0).positive&&(e.clauses.get(0).literals.get(0).predicate.equals("p1")||e.clauses.get(0).literals.get(0).predicate.equals("p2"))))),"only original premises and whole candidate, no private or derived primary import");}
            System.out.println("VARIABLES conflict="+conflict+" negative="+negative+" reverse="+reverse+" native="+nativePath+" diagnosticBarriers="+diagnostic.qualification.completedBarriers+" primary="+current.primary.size());
        }
        try(ContextSevenPremiseNativeWriteRunner.Fixture f=new ContextSevenPremiseNativeWriteRunner.Fixture(dir,name)){ContextProductionInventory inv=ContextSevenPremiseNativeWriteRunner.inventory(f);require(f.db.getRevision()>=settled&&inv.primary.size()==(conflict?2:3)&&ContextSevenPremiseNativeWriteRunner.origins(inv).equals(persisted)&&ContextSevenPremiseNativeWriteRunner.pins(f).equals(pins),"reopen retains exactly original premises plus optional candidate and all pins");}
    }
    static void run(boolean reverse,boolean negative,boolean conflict,String marker){run(reverse,negative,conflict,false,marker);}
    static void runPermutation(boolean reverse,boolean negative,boolean swappedBridge,String marker){run(reverse,negative,swappedBridge,true,marker);}
    static void run(boolean reverse,boolean negative,boolean conflict,boolean permuted,String marker){try{
        Path dir=Files.createTempDirectory("authority-variables-");System.setProperty("user.home",dir.toString());String sign=negative?"~":"";
        if(permuted){ContextAuthorityChain.create(dir,"A1","!@a @b "+sign+"q(a,b);");ContextAuthorityChain.create(dir,"A2","!@d @c "+sign+"q(c,d);");ContextAuthorityChain.create(dir,"A3","!@f @e "+sign+"q(e,f);");ContextAuthorityChain.create(dir,"Bridge1","!@n @m "+sign+"out(m,n)->"+sign+(conflict?"mid(n,m);":"mid(m,n);"));ContextAuthorityChain.create(dir,"Bridge2","!@r @s "+sign+"out(r,s)->"+sign+(conflict?"mid(s,r);":"mid(r,s);"));}
        else{for(String name:new String[]{"A1","A2","A3"})ContextAuthorityChain.create(dir,name,"!@x @y "+sign+"q(x,y);");for(String name:new String[]{"Bridge1","Bridge2"})ContextAuthorityChain.create(dir,name,"!@x @y "+sign+"out(x,y)->"+sign+"mid(x,y);");}
        ContextAuthorityChain.create(dir,"Deny","!"+(negative?"":"~")+"mid(1,2);");String text=permuted?"!@v @u "+sign+"q(u,v)&&~p1(u)&&~p2(v)->"+sign+"out(v,u);":"!@x @y "+sign+"q(x,y)&&~p1(x)&&~p2(y)->"+sign+(conflict?"out(x,y);":"out(x,x);");
        caseOf(dir,"Public",reverse,negative,conflict,false,text,permuted);caseOf(dir,"Native",reverse,negative,conflict,true,text,permuted);
        System.out.println(marker+" checks="+(checks+ContextAuthorityChain.checks));System.exit(0);
    }catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
}
